mapper.select:
SELECT COUNT(*) 
FROM ORDERS o 
WHERE o.member_no = #{memberNo}


        AND o.order_date >= ADD_MONTHS(SYSDATE, -6)


        AND TO_CHAR(o.order_date, 'YYYY') = #{yearFilter}

SELECT * FROM ( SELECT o.order_no AS orderNo, o.member_no AS memberNo, o.order_date AS orderDate, o.order_status AS orderStatus, o.total_price AS totalPrice, o.delivery_fee AS deliveryFee, od.order_detail_no AS orderDetailNo, od.order_qty AS quantity, od.price AS itemPrice, p.product_no AS productNo, p.product_name AS productName, po.option1_type AS option1Type, po.option1_value AS option1Value, po.option2_type AS option2Type, po.option2_value AS option2Value, img.IMAGE_URL AS imageUrl FROM ORDERS o JOIN ORDER_DETAIL od ON o.order_no = od.order_no JOIN PRODUCT p ON od.product_no = p.product_no LEFT JOIN PRODUCT_OPTION po ON od.option_id = po.option_id LEFT JOIN ( SELECT product_no, image_url FROM ( SELECT product_no, image_url, ROW_NUMBER() OVER(PARTITION BY product_no ORDER BY image_no ASC) as rn FROM PRODUCT_IMAGE WHERE image_purpose = '대표' ) WHERE rn = 1 ) img ON p.product_no = img.product_no WHERE o.member_no = #{memberNo} AND o.order_no IN ( SELECT order_no FROM ( SELECT order_no, ROWNUM as rnum FROM ( SELECT DISTINCT order_no, order_date FROM ORDERS WHERE member_no = #{memberNo}
AND order_date >= ADD_MONTHS(SYSDATE, -6)
AND TO_CHAR(order_date, 'YYYY') = #{yearFilter}
ORDER BY order_date DESC, order_no DESC ) WHERE ROWNUM <= #{endRow} ) WHERE rnum >= #{startRow} ) ) ORDER BY orderDate DESC, orderNo DESC, orderDetailNo ASC
